fn all_names(deps: Map[Str, List[Str]]) -> List[Str] {
  let from_keys = deps.keys()
  let from_lists = deps.values().flatten()
  return from_keys.concat(from_lists).unique().sort()
}

fn ready_next(deps: Map[Str, List[Str]], done: List[Str], names: List[Str]) -> Option[Str] {
  return names.find(fn(n) => (not (done.contains(n))) and deps.get(n).unwrap_or([]).all(fn(d) => done.contains(d)))
}

pub fn topo(deps: Map[Str, List[Str]]) -> Result[List[Str], Str] {
  let names = all_names(deps)
  var done: List[Str] = []
  while done.len() < names.len() {
    match ready_next(deps, done, names) {
      Some(n) => { done = done.push(n) },
      None => { return Err("cycle") },
    }
  }
  return Ok(done)
}
